// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "I have a my apps linux container running at 192.168.100.125. could you remake the app using tanstack and have the state of it persist with a local sqlite database. also use React for the UI with components from: https://www.reactbits.dev/. after you are done could you deploy it onto the container."
// Changes: Project editor route – loads the project from SQLite, GooeyNav tabs in the URL, autosave status,
//          rename, conflict resolution banner and JSON import into the project.

import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { useServerFn } from '@tanstack/react-start'
import { useCallback, useDeferredValue, useMemo, useRef, useState } from 'react'
import { DefinitionTab } from '#/components/DefinitionTab'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "i changed my mind move the previous pane and this one into separate \"overview\" tab"
// Changes: Overview tab.
import { OverviewTab } from '#/components/OverviewTab'
import { ExportTab } from '#/components/ExportTab'
import { HistoryTab } from '#/components/HistoryTab'
import { LLTab, type LLMode } from '#/components/LLTab'
import { PrecTab } from '#/components/PrecTab'
import GooeyNav from '#/components/reactbits/GooeyNav'
import { useToast } from '#/components/Toasts'
import { Button, PrimaryButton, cx } from '#/components/ui'
import { parseDecls } from '#/lib/definition'
import { analyzeLL, parseGrammar } from '#/lib/grammar'
import type { ProjectData } from '#/lib/project'
import { useAutosave, type SaveStatus } from '#/lib/useAutosave'
import { getProjectFn, importIntoProjectFn, renameProjectFn } from '#/server/projects.functions'
import type { ProjectRecord } from '#/server/projects.server'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "could you add a tab where i will be able to define properties"
// Changes: New Definition tab (G = (N, T, P, S)) in front of the LL tab.
const TABS = [
  { id: 'def', label: 'Definícia' },
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "i changed my mind move the previous pane and this one into separate \"overview\" tab"
  // Changes: New Prehľad (overview) tab.
  { id: 'overview', label: 'Prehľad' },
  { id: 'll', label: 'LL' },
  { id: 'prec', label: 'Precedencia' },
  { id: 'export', label: 'Export' },
  { id: 'history', label: 'História' },
] as const

type TabId = (typeof TABS)[number]['id']
const isTab = (v: unknown): v is TabId => TABS.some((t) => t.id === v)
const isLLMode = (v: unknown): v is LLMode => v === 'sim' || v === 'view'

export const Route = createFileRoute('/p/$projectId')({
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
  // Changes: The grammar is entered in the Definition tab, so it is the default tab.
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
  // Changes: Optional LL mode in the URL (sim = simulation, view = viewer); absent means simulation.
  validateSearch: (search: Record<string, unknown>): { tab: TabId; mode?: LLMode } => ({
    tab: isTab(search.tab) ? search.tab : 'def',
    ...(isLLMode(search.mode) ? { mode: search.mode } : {}),
  }),
  loader: async ({ params }) => {
    const project = await getProjectFn({ data: { id: params.projectId } })
    if (!project) throw notFound()
    return project
  },
  // Switching tabs must not refetch (the editor owns the live copy); leaving the page drops the cache.
  staleTime: Infinity,
  gcTime: 0,
  head: ({ loaderData }) => ({ meta: [{ title: `${loaderData?.name ?? 'Projekt'} · IFJ26 Table Maker` }] }),
  component: ProjectPage,
  notFoundComponent: () => (
    <main className="mx-auto max-w-xl px-4 py-24 text-center">
      <h1 className="text-2xl font-semibold">Projekt neexistuje</h1>
      <Link to="/" className="mt-4 inline-block text-indigo-300 hover:text-indigo-200">
        ← Späť na projekty
      </Link>
    </main>
  ),
})

function ProjectPage() {
  const project = Route.useLoaderData()
  return <Editor key={project.id} project={project} />
}

const STATUS: Record<SaveStatus, { text: string; dot: string }> = {
  saved: { text: 'Uložené', dot: 'bg-emerald-400' },
  pending: { text: 'Neuložené zmeny', dot: 'bg-amber-400' },
  saving: { text: 'Ukladám…', dot: 'bg-sky-400 animate-pulse' },
  error: { text: 'Chyba ukladania – skúšam znova', dot: 'bg-rose-400' },
  conflict: { text: 'Konflikt verzií', dot: 'bg-rose-400' },
}

function Editor({ project }: { project: ProjectRecord }) {
  const { tab, mode } = Route.useSearch()
  const navigate = Route.useNavigate()
  const toast = useToast()
  const renameFn = useServerFn(renameProjectFn)
  const importFn = useServerFn(importIntoProjectFn)

  const [data, setData] = useState(project.data)
  const dataRef = useRef(data)
  const [name, setName] = useState(project.name)
  const savedName = useRef(project.name)
  const [conflict, setConflict] = useState<ProjectRecord | null>(null)
  const autosave = useAutosave(project, setConflict)
  const { queue, adopt, flush } = autosave

  const update = useCallback(
    (fn: (d: ProjectData) => ProjectData) => {
      const next = fn(dataRef.current)
      dataRef.current = next
      setData(next)
      queue(next)
    },
    [queue],
  )

  const replaceAll = useCallback(
    (record: ProjectRecord) => {
      dataRef.current = record.data
      setData(record.data)
      adopt(record)
      setConflict(null)
    },
    [adopt],
  )

  const grammar = useDeferredValue(data.ll.grammar)
  const parsed = useMemo(() => parseGrammar(grammar), [grammar])
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
  // Changes: LL analysis runs on the whole definition G = (N, T, P, S) from the Definition tab.
  const def = useDeferredValue(data.def)
  const analysis = useMemo(() => {
    if (!parsed.rules.length) return null
    const symbols = (text: string) => parseDecls(text).map((d) => d.symbol)
    return analyzeLL(parsed.rules, def.start, { N: symbols(def.nonterminals), T: symbols(def.terminals) })
  }, [parsed, def])

  const commitName = async () => {
    const next = name.trim()
    if (!next) return setName(savedName.current)
    if (next === savedName.current) return
    try {
      await renameFn({ data: { id: project.id, name: next } })
      savedName.current = next
      document.title = `${next} · IFJ26 Table Maker`
    } catch (err) {
      setName(savedName.current)
      toast({ title: 'Premenovanie zlyhalo', description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    }
  }

  const importData = async (imported: ProjectData, fileName: string) => {
    await flush()
    const record = await importFn({ data: { id: project.id, data: imported, label: `Pred importom ${fileName}` } })
    if (!record) throw new Error('Projekt už neexistuje')
    replaceAll(record)
    toast({ title: 'Projekt importovaný', description: fileName, tone: 'ok' })
  }

  const status = STATUS[autosave.status]
  const activeIndex = TABS.findIndex((t) => t.id === tab)

  return (
    // overflow-x-clip: GooeyNav's goo canvas reaches past the viewport edge on phones (clip keeps the header sticky).
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "make the right pane scrollable insted it being rendered whole, the page should stay constant"
    // Changes: Definícia tab on wide screens – small bottom padding so the page itself fits the viewport (columns scroll inside).
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
    // Changes: The LL tab also fits the viewport (its columns scroll inside).
    <div className={cx('mx-auto max-w-[1440px] overflow-x-clip px-4 pb-16 sm:px-6', (tab === 'def' || tab === 'll') && 'lg:pb-3')}>
      <header className="sticky top-0 z-20 -mx-4 mb-5 border-b border-white/5 bg-[#07080c]/85 px-4 py-3 backdrop-blur-xl sm:-mx-6 sm:px-6">
        <div className="flex flex-wrap items-center gap-x-4 gap-y-3">
          <Link to="/" className="text-sm text-zinc-400 hover:text-zinc-100">
            ← Projekty
          </Link>
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            onBlur={() => void commitName()}
            onKeyDown={(e) => e.key === 'Enter' && e.currentTarget.blur()}
            maxLength={120}
            aria-label="Názov projektu"
            className="min-w-0 flex-1 basis-48 rounded-lg border border-transparent bg-transparent px-2 py-1 text-lg font-semibold text-zinc-100 hover:border-white/10 focus:border-indigo-400/50 focus:outline-none"
          />
          <div className="flex items-center gap-2 text-xs text-zinc-400" role="status" aria-live="polite">
            <span className={cx('h-2 w-2 rounded-full', status.dot)} />
            {status.text}
            {autosave.status === 'saved' && <span className="text-zinc-600">{new Date(autosave.savedAt).toLocaleTimeString('sk-SK')}</span>}
          </div>
          <GooeyNav
            items={TABS.map((t) => ({ label: t.label }))}
            activeIndex={activeIndex}
            // AI generated by: Claude Code / claude-opus-5-5
            // Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
            // Changes: Switching tabs keeps the chosen LL mode.
            onChange={(index) => void navigate({ search: (prev) => ({ ...prev, tab: TABS[index].id }), replace: true })}
            theme="dark"
            size="sm"
            color="#e0e7ff"
            // AI generated by: Claude Code / claude-opus-5-5
            // Prompt: "could you add a tab where i will be able to define properties"
            // Changes: Tighter tab padding on phones so all five tabs fit on one line.
            // AI generated by: Claude Code / claude-opus-5-5
            // Prompt: "i changed my mind move the previous pane and this one into separate \"overview\" tab"
            // Changes: Six tabs now – even tighter padding, smaller text and no gap on phones to keep one line.
            className="w-full justify-center lg:w-auto max-sm:[&_li>*]:px-[5px]! max-sm:[&_li>*]:text-xs! max-sm:[&_ul]:gap-0!"
          />
        </div>
      </header>

      {conflict && (
        <div className="mb-5 flex flex-wrap items-center gap-3 rounded-2xl border border-rose-400/30 bg-rose-500/10 px-4 py-3 text-sm text-rose-100">
          <div className="min-w-0 flex-1">
            Projekt medzitým zmenil niekto iný (iná karta alebo kolega, {new Date(conflict.updatedAt).toLocaleTimeString('sk-SK')}). Tvoje zmeny zatiaľ
            neboli uložené.
          </div>
          <Button onClick={() => replaceAll(conflict)}>Načítať verziu zo servera</Button>
          <PrimaryButton
            onClick={() => {
              autosave.overwrite(conflict, dataRef.current)
              setConflict(null)
            }}
          >
            Prepísať mojou verziou
          </PrimaryButton>
        </div>
      )}

      {/* AI generated by: Claude Code / claude-opus-5-5
          Prompt: "could you add a tab where i will be able to define properties"
          Changes: Render the Definition tab. */}
      {tab === 'def' && <DefinitionTab data={data} update={update} analysis={analysis} errors={parsed.errors} />}
      {/* AI generated by: Claude Code / claude-opus-5-5
          Prompt: "i changed my mind move the previous pane and this one into separate \"overview\" tab"
          Changes: Overview tab. */}
      {tab === 'overview' && <OverviewTab data={data} analysis={analysis} errors={parsed.errors} />}
      {/* AI generated by: Claude Code / claude-opus-5-5
          Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
          Changes: LL tab gets its mode from the URL. */}
      {tab === 'll' && (
        <LLTab
          data={data}
          update={update}
          analysis={analysis}
          errors={parsed.errors}
          mode={mode ?? 'sim'}
          onMode={(m) => void navigate({ search: (prev) => ({ ...prev, mode: m }), replace: true })}
        />
      )}
      {tab === 'prec' && <PrecTab data={data} update={update} />}
      {tab === 'export' && <ExportTab name={name} data={data} update={update} analysis={analysis} onImport={importData} />}
      {tab === 'history' && <HistoryTab projectId={project.id} flush={flush} onRestored={replaceAll} />}
    </div>
  )
}
